@import "@fontsource-variable/montserrat";

/* Light (faithful): pale blush page and bands, brick red for whole bands and the pill
   button with white text on it, peach pattern lines, a near-black brown for media tints. */
:root {
  --background: oklch(0.944 0.023 41);
  --foreground: oklch(0.506 0.142 25);
  --card: oklch(0.975 0.012 41);
  --card-foreground: oklch(0.506 0.142 25);
  --popover: oklch(0.975 0.012 41);
  --popover-foreground: oklch(0.506 0.142 25);
  --primary: oklch(0.506 0.142 25);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.359 0.09 24);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.9 0.035 38);
  --muted-foreground: oklch(0.56 0.11 27);
  --accent: oklch(0.91 0.04 38);
  --accent-foreground: oklch(0.506 0.142 25);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.506 0.142 25);
  --input: oklch(0.506 0.142 25);
  --ring: oklch(0.506 0.142 25);
  --highlight: oklch(0.79 0.09 40);
  --highlight-foreground: oklch(0.359 0.09 24);
  --glow: oklch(0.12 0.015 23);
  --chart-1: oklch(0.506 0.142 25);
  --chart-2: oklch(0.79 0.09 40);
  --chart-3: oklch(0.359 0.09 24);
  --chart-4: oklch(0.9 0.035 38);
  --chart-5: oklch(0.12 0.015 23);
  --sidebar: oklch(0.506 0.142 25);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(1 0 0);
  --sidebar-primary-foreground: oklch(0.506 0.142 25);
  --sidebar-accent: oklch(0.46 0.13 25);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 35%);
  --sidebar-ring: oklch(1 0 0);

  --typeface-body: "Montserrat Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Montserrat Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 2.5rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 14.5rem;
  }
}

/* Dark (sibling): oxblood-black page, blush text, the same red for whole bands. */
.dark {
  --background: oklch(0.2 0.03 24);
  --foreground: oklch(0.93 0.025 40);
  --card: oklch(0.25 0.04 24);
  --card-foreground: oklch(0.93 0.025 40);
  --popover: oklch(0.25 0.04 24);
  --popover-foreground: oklch(0.93 0.025 40);
  --primary: oklch(0.54 0.145 25);
  --primary-foreground: oklch(0.985 0.005 40);
  --secondary: oklch(0.3 0.07 24);
  --secondary-foreground: oklch(0.93 0.025 40);
  --muted: oklch(0.27 0.045 24);
  --muted-foreground: oklch(0.75 0.06 35);
  --accent: oklch(0.3 0.06 24);
  --accent-foreground: oklch(0.93 0.025 40);
  --destructive: oklch(0.64 0.19 27);
  --destructive-foreground: oklch(0.985 0.005 40);
  --border: oklch(0.72 0.1 32);
  --input: oklch(0.72 0.1 32);
  --ring: oklch(0.79 0.09 40);
  --highlight: oklch(0.72 0.1 38);
  --highlight-foreground: oklch(0.2 0.03 24);
  --glow: oklch(0.12 0.02 23);
  --chart-1: oklch(0.54 0.145 25);
  --chart-2: oklch(0.72 0.1 38);
  --chart-3: oklch(0.93 0.025 40);
  --chart-4: oklch(0.3 0.07 24);
  --chart-5: oklch(0.12 0.02 23);
  --sidebar: oklch(0.54 0.145 25);
  --sidebar-foreground: oklch(0.985 0.005 40);
  --sidebar-primary: oklch(0.985 0.005 40);
  --sidebar-primary-foreground: oklch(0.54 0.145 25);
  --sidebar-accent: oklch(0.48 0.13 25);
  --sidebar-accent-foreground: oklch(0.985 0.005 40);
  --sidebar-border: oklch(1 0 0 / 30%);
  --sidebar-ring: oklch(0.985 0.005 40);
}
